# Smooth mirrored silhouettes from right-half outline points (Catmull-Rom -> cubic Bezier)
def cr_path(pts, closed=True, t=0.5):
    n=len(pts); d=f"M{pts[0][0]:.2f},{pts[0][1]:.2f} "
    rng=range(n if closed else n-1)
    for i in rng:
        p0=pts[(i-1)%n] if closed or i>0 else pts[0]; p1=pts[i]; p2=pts[(i+1)%n]; p3=pts[(i+2)%n] if closed or i+2<n else pts[-1]
        c1=(p1[0]+(p2[0]-p0[0])*t/3, p1[1]+(p2[1]-p0[1])*t/3)
        c2=(p2[0]-(p3[0]-p1[0])*t/3, p2[1]-(p3[1]-p1[1])*t/3)
        d+=f"C{c1[0]:.2f},{c1[1]:.2f} {c2[0]:.2f},{c2[1]:.2f} {p2[0]:.2f},{p2[1]:.2f} "
    return d+("Z" if closed else "")
def mirror(right):
    # right: list from top-center (x=0) down to bottom-center (x=0)
    left=[(-x,y) for x,y in reversed(right[1:-1])]
    return right+left
