def sil(name,x,y,h,fill,rim=None,rim_side=1,rimw=2.5,flip=False,head=None,hair=None,skin=None,tilt=0,inner=None,op=1):
    s=h/100.0; sx=-s if flip else s
    tf=f'translate({x},{y}) rotate({tilt}) scale({sx},{s})'
    d=shape(name); out=''
    if rim:
        ox=rimw*rim_side; out+=f'<path d="{d}" fill="{rim}" transform="translate({x+ox},{y-abs(ox)*0.3}) rotate({tilt}) scale({sx},{s})"/>'
    out+=f'<path d="{d}" fill="{fill}" transform="{tf}"/>'
    det=''
    if head=='man' and skin:
        det+=f'<ellipse cx="0" cy="-93" rx="5.4" ry="6.6" fill="{skin}"/>'
        det+=f'<path d="M-5.9,-92.5 C-6.4,-101 6.4,-101 5.9,-92.5 C4.5,-96 -4.5,-96 -5.9,-92.5 Z" fill="{hair or "#15110e"}"/>'
    if head=='back':
        det+=f'<ellipse cx="0" cy="-93" rx="5.8" ry="6.9" fill="{hair or "#15110e"}"/><rect x="-2.6" y="-87" width="5.2" height="2.5" fill="{skin or "#5a3a28"}"/>'
    if head=='woman' and skin:
        det+=f'<ellipse cx="0" cy="-91" rx="4.6" ry="5.8" fill="{skin}"/>'
    if inner: det+=inner
    if det: out+=f'<g transform="{tf}">{det}</g>'
    return f'<g opacity="{op}">{out}</g>' if op!=1 else out
