def kabir_profile(fill='#14110f',rim='#f2cf9c',rimw=5,hair='#0b0908',skin_glow=None):
    face=cr_path(KABIR_PROFILE)
    out=f'<path d="{face}" fill="{rim}" transform="translate({-rimw},{-rimw*0.4})"/>'
    out+=f'<path d="{face}" fill="{fill}"/>'
    if skin_glow: out+=f'<path d="{face}" fill="{skin_glow}"/>'
    out+=f'<path d="{cr_path(KABIR_HAIR)}" fill="{hair}"/>'
    # stubble breakup along jaw rim
    out+=''.join(f'<circle cx="{x}" cy="{y}" r="2.2" fill="{fill}"/>' for x,y in [(338,640),(345,652),(356,664),(368,672),(381,680),(334,620),(336,604)])
