    out+=f'<path d="M610,420 C640,410 660,440 650,480 C642,515 620,520 608,505" fill="none" stroke="{rim}" stroke-opacity="0.25" stroke-width="3"/>'
    # eye glint
    out+=f'<ellipse cx="352" cy="380" rx="6" ry="3" fill="#f6dcb0" fill-opacity="0.55"/>'
    return out

